// 参考解：头插法就地逆置
#include <iostream>
using namespace std;

struct LNode {
    int data;
    LNode *next;
};

typedef LNode *LinkList;

int main() {
    int n;
    if (!(cin >> n)) return 0;

    LinkList L = new LNode;
    L->next = nullptr;
    LNode *r = L;
    for (int i = 0; i < n; i++) {
        int v; cin >> v;
        LNode *s = new LNode;
        s->data = v; s->next = nullptr;
        r->next = s; r = s;
    }

    LNode *p = L->next, *q = nullptr;
    L->next = nullptr;
    while (p != nullptr) {
        q = p->next;        // ① 记住后继
        p->next = L->next;  // ② 接到新表头
        L->next = p;        // ③ 成为新表头
        p = q;              // ④ 继续
    }

    if (L->next == nullptr) {
        cout << "empty\n";
    } else {
        for (LNode *t = L->next; t != nullptr; t = t->next) {
            cout << t->data << (t->next == nullptr ? '\n' : ' ');
        }
    }
    return 0;
}
